use mg_core::CoreRng;

use crate::model::Word;
use crate::settings::{DayNumber, Language, WordLength};

// Generated by tools/word-lists/generate.py; see its README for sources and licenses.
const RUSSIAN: &str = include_str!("../../data/ru-answers.txt");
const ENGLISH: &str = include_str!("../../data/en-answers.txt");

/// Seed of the fixed order the daily words follow: changing it changes every past daily word.
const DAILY_ORDER_SEED: u64 = 0x5752_4448_554E_5401;

/// The words the game may ask for, per language and length (built into the game).
#[derive(Clone, Copy, Debug)]
pub(crate) struct Answers {
    language: Language,
    length: WordLength,
}

impl Answers {
    pub(crate) fn new(language: Language, length: WordLength) -> Self {
        Self { language, length }
    }

    /// The `answers <length>` section of the language's list.
    fn texts(self) -> impl Iterator<Item = &'static str> {
        let source = match self.language {
            Language::Russian => RUSSIAN,
            Language::English => ENGLISH,
        };
        let wanted = self.length.get();
        let mut in_section = false;
        source.lines().filter(move |line| {
            if line.starts_with('#') {
                return false;
            }
            if let Some(length) = line.strip_prefix("answers ") {
                in_section = length.parse::<u32>().ok() == Some(wanted);
                return false;
            }
            in_section
        })
    }

    pub(crate) fn count(self) -> usize {
        self.texts().count()
    }

    fn nth(self, index: usize) -> Option<Word> {
        let text = self.texts().nth(index)?;
        Word::parse(text, self.language, self.length).ok()
    }

    pub(crate) fn random(self, rng: &mut CoreRng) -> Option<Word> {
        self.nth(rng.index(self.count())?)
    }

    /// Every language walks its answers in one fixed shuffled order, a word a day, so the
    /// daily word does not follow the alphabet and repeats only after the whole list.
    pub(crate) fn daily(self, day: DayNumber) -> Option<Word> {
        let count = self.count();
        let mut order: Vec<usize> = (0..count).collect();
        CoreRng::derive(DAILY_ORDER_SEED, u64::from(self.language.hash_code())).shuffle(&mut order);
        let position = usize::try_from(day.get()).ok()?.checked_rem(count)?;
        self.nth(*order.get(position)?)
    }

    #[cfg(test)]
    pub(crate) fn all(self) -> impl Iterator<Item = &'static str> {
        self.texts()
    }
}
